#!/usr/bin/env bash
# M1b: the v1.3 bridge's Remotion renders (production log):
#   M7-O18-Whiteboard   the whiteboard texture for the M7 render, written in on the v1.3 lines (O18's marks), the July
#                       fix circled: a JPEG q95 sequence at 1800x1125 (scale 0.75; M5's movie was 1200x750, soft in
#                       O18d's close) -> assets/gen/tex/m1b/M7-O18-Whiteboard/frames/<n>.jpeg (out of the manifest,
#                       regenerated by this script). blender/look.py maps it like the M7b screens.
#   M7-O18-DenialTags   the two denial tags over O18 (transparent, full size, ProRes 4444) -> renders/m1b/remotion/,
#                       pinned by timing/o18_pins.json (blender/o18_pins.py), for the M7 assembly.
# Same flags as scripts/m5_remotion.sh and scripts/m7b_remotion.sh (CPU, --gl=swangle, concurrency 2).
# Usage: scripts/m1b_remotion.sh [composition-id ...]   (no args: both)
set -euo pipefail
cd "$(git rev-parse --show-toplevel)"
quiet() { grep -v -i -e zod -e "version mismatch" -e "^-*$" -e "wrong versions" -e "breakages" -e "React context" -e "Type errors" \
  -e "Failed renders" -e "resolve:" -e "package.json has" -e "Remove the" -e "Run .npx" -e "^$" || true; }
SEL=("$@")
want() { [ ${#SEL[@]} -eq 0 ] || [[ " ${SEL[*]} " =~ " $1 " ]]; }
if want M7-O18-Whiteboard; then
  t=$(date +%s); out=assets/gen/tex/m1b/M7-O18-Whiteboard/frames; mkdir -p "$out"
  npx remotion render M7-O18-Whiteboard "$out" --sequence --image-sequence-pattern="[frame].[ext]" --image-format=jpeg --jpeg-quality=95 \
    --scale=0.75 --gl=swangle --concurrency=2 --log=error 2>&1 | quiet
  echo "M7-O18-Whiteboard: $(ls "$out" | wc -l) frames, $(( $(date +%s) - t )) s"
fi
if want M7-O18-DenialTags; then
  t=$(date +%s); out=renders/m1b/remotion; mkdir -p "$out"
  npx remotion render M7-O18-DenialTags "$out/M7-O18-DenialTags.mov" --codec=prores --prores-profile=4444 --pixel-format=yuva444p10le \
    --image-format=png --gl=swangle --concurrency=2 --log=error 2>&1 | quiet
  echo "M7-O18-DenialTags.mov $(( $(date +%s) - t )) s"
fi
